command:
$ErrorActionPreference="Stop"
$repo=$env:FLYEXPLORER_CANONICAL_CHECKOUT
Set-Location -LiteralPath $repo
& git fetch origin main work/remote-command-exit-semantics-20261005 --no-tags --prune
if($LASTEXITCODE -ne 0){throw "cleanup fetch failed"}
& git diff --quiet refs/remotes/origin/main refs/remotes/origin/work/remote-command-exit-semantics-20261005 --
if($LASTEXITCODE -ne 0){throw "refuse cleanup: merged main tree differs from work branch tree"}
& git push origin --delete work/remote-command-exit-semantics-20261005
if($LASTEXITCODE -ne 0){throw "failed to delete merged work branch"}
& git fetch origin --prune --no-tags
if($LASTEXITCODE -ne 0){throw "post-delete fetch failed"}
if(& git show-ref --verify --quiet "refs/remotes/origin/work/remote-command-exit-semantics-20261005"){
  throw "branch still exists: work/remote-command-exit-semantics-20261005"
}
Write-Host "REMOTE_COMMAND_EXIT_BRANCH_CLEANUP=PASS"
